// ─── Israeli store link guard ──────────────────────────────────────
// Returns true only if a purchase link belongs to a genuine Israeli store.
// Cross-border fakers (desertcart.co.il etc.) are blocked first even if .co.il.
const CROSS_BORDER_FAKERS_FE = new Set([
  "desertcart.co.il", "desertcart.com", "desertcart.ae",
  "joom.co.il", "joom.com",
  "banggood.co.il", "banggood.com",
  "aliexpress.co.il", "aliexpress.com",
  "gearbest.co.il", "gearbest.com",
  "dhgate.co.il", "dhgate.com",
  "noon.co.il", "noon.com",
  "shein.co.il", "temu.co.il", "wish.co.il",
]);
const ISRAELI_COM_STORES_FE = new Set([
  "terminalx.com",  // Israeli chain
  "ksp.com",        // KSP .com mirror
  "apple.com",      // apple.com/il-he — Israeli Apple storefront
  "samsung.com",    // samsung.com/il — Israeli Samsung store
]);
function isIsraeliLink(url = "") {
  if (!url) return false;
  try {
    const domain = new URL(url).hostname.replace(/^www\./, "");
    // ❌ Block cross-border fakers FIRST — even if they have .co.il
    if (CROSS_BORDER_FAKERS_FE.has(domain)) return false;
    // ✅ Accept genuine Israeli TLDs
    if (domain.endsWith(".co.il") || domain.endsWith(".net.il") ||
        domain.endsWith(".org.il") || domain.endsWith(".ac.il")) return true;
    // ✅ Accept known Israeli .com stores
    if (ISRAELI_COM_STORES_FE.has(domain)) return true;
    return false;
  } catch { return false; }
}
const MIN_UNDERCUT = 18;

