// Returns list of competitor query strings for a given search result
function getCompetitors(productName, modelQuery) {
  const search = (productName || modelQuery || "").toLowerCase();
  for (const [key, rivals] of Object.entries(COMPETITORS)) {
    if (search.includes(key)) return rivals;
  }
  return [];
}

