// ─────────────────────────────────────────────────────────────────
//  TIERED PRICING — generates price tiers from a base market price
// ─────────────────────────────────────────────────────────────────
function makeTiers(marketMin) {
  const r = Math.round;
  return [
    { people: 5,   price: r(marketMin * 0.97), label: "כניסה לקבוצה" },
    { people: 10,  price: r(marketMin * 0.91), label: "הנחה ראשונה" },
    { people: 20,  price: r(marketMin * 0.83), label: "מחיר טוב" },
    { people: 40,  price: r(marketMin * 0.74), label: "מחיר מצוין" },
    { people: 75,  price: r(marketMin * 0.63), label: "מחיר סיטונאי" },
  ];
}

// Which tier is active given current participant count
function activeTier(tiers, participants) {
  let active = null;
  for (const tier of tiers) {
    if (participants >= tier.people) active = tier;
  }
  return active; // null = not even first tier yet
}

// Next tier to unlock
function nextTier(tiers, participants) {
  return tiers.find(t => participants < t.people) || null;
}

// ─────────────────────────────────────────────────────────────────
//  STREAMING ROAD BANNER
//  Shows a Bundly-branded road scene while category results load.
//  The car stops at each store, showing a real price from found products.
// ─────────────────────────────────────────────────────────────────
function StreamingRoadBanner({ count = 0, phase = "streaming", products = [] }) {
  // Take up to 5 priced products for the store price bubbles
  const priced = products.filter(p => p.priceMin > 0).slice(0, 5);
  const storeConfigs = [
    { pct: 11, wall: '#fef3c7', roof: '#f59e0b' },
    { pct: 27, wall: '#ede9fe', roof: '#7c3aed' },
    { pct: 45, wall: '#dcfce7', roof: '#16a34a' },
    { pct: 63, wall: '#fee2e2', roof: '#dc2626' },
    { pct: 79, wall: '#dbeafe', roof: '#2563eb' },
  ].map((s, i) => ({
    ...s,
    price: priced[i] ? `₪${priced[i].priceMin.toLocaleString()}` : null,
  }));

  // Layout constants (px)
  const H = 76, SKY = 26, WALK = 10, ROAD = 22;
  const roadTop = SKY + WALK;          // 36
  const roadBot = roadTop + ROAD;      // 58
  const storeBotFromBot = H - roadTop; // 40  (store base sits at road top)
  const carBotFromBot   = H - roadBot; // 18  (car bottom at road bottom)
  const DUR = "11s";

  return (
    <>
      <style>{`
        @keyframes srCar {
          0%     { left:-4%  }
          8%     { left:9%   }
          15%    { left:9%   }
          23%    { left:25%  }
          30%    { left:25%  }
          38%    { left:43%  }
          45%    { left:43%  }
          54%    { left:61%  }
          61%    { left:61%  }
          70%    { left:77%  }
          77%    { left:77%  }
          87%    { left:104% }
          87.01% { left:-4%  }
          100%   { left:-4%  }
        }
        @keyframes srP1{0%,7%{opacity:0;transform:translateX(-50%) scale(.4) translateY(6px)}11%{opacity:1;transform:translateX(-50%) scale(1) translateY(0)}14%{opacity:1}18%{opacity:0;transform:translateX(-50%) scale(.7) translateY(-4px)}100%{opacity:0}}
        @keyframes srP2{0%,22%{opacity:0;transform:translateX(-50%) scale(.4) translateY(6px)}26%{opacity:1;transform:translateX(-50%) scale(1) translateY(0)}29%{opacity:1}33%{opacity:0;transform:translateX(-50%) scale(.7) translateY(-4px)}100%{opacity:0}}
        @keyframes srP3{0%,37%{opacity:0;transform:translateX(-50%) scale(.4) translateY(6px)}41%{opacity:1;transform:translateX(-50%) scale(1) translateY(0)}44%{opacity:1}48%{opacity:0;transform:translateX(-50%) scale(.7) translateY(-4px)}100%{opacity:0}}
        @keyframes srP4{0%,53%{opacity:0;transform:translateX(-50%) scale(.4) translateY(6px)}57%{opacity:1;transform:translateX(-50%) scale(1) translateY(0)}60%{opacity:1}64%{opacity:0;transform:translateX(-50%) scale(.7) translateY(-4px)}100%{opacity:0}}
        @keyframes srP5{0%,69%{opacity:0;transform:translateX(-50%) scale(.4) translateY(6px)}73%{opacity:1;transform:translateX(-50%) scale(1) translateY(0)}76%{opacity:1}80%{opacity:0;transform:translateX(-50%) scale(.7) translateY(-4px)}100%{opacity:0}}
      `}</style>

      <div style={{
        position:'relative', width:'100%', height:H,
        borderRadius:14, overflow:'hidden', marginBottom:14,
        border:'1px solid #e0e7ff',
        boxShadow:'0 2px 10px rgba(99,102,241,0.1)',
      }}>
        {/* ── Sky ────────────────────────────────────── */}
        <div style={{position:'absolute',inset:0,top:0,height:SKY,background:'linear-gradient(to bottom,#bfdbfe,#93c5fd)'}}/>

        {/* Clouds */}
        <div style={{position:'absolute',top:5,left:'17%',width:42,height:12,background:'rgba(255,255,255,0.8)',borderRadius:10}}/>
        <div style={{position:'absolute',top:9,left:'52%',width:30,height:9,background:'rgba(255,255,255,0.6)',borderRadius:8}}/>
        <div style={{position:'absolute',top:4,left:'73%',width:50,height:14,background:'rgba(255,255,255,0.7)',borderRadius:12}}/>

        {/* ── Sidewalk ───────────────────────────────── */}
        <div style={{position:'absolute',top:SKY,left:0,right:0,height:WALK,background:'#d1d5db'}}/>
        <div style={{position:'absolute',top:SKY,left:0,right:0,height:1,background:'#9ca3af'}}/>

        {/* ── Road ──────────────────────────────────── */}
        <div style={{position:'absolute',top:roadTop,left:0,right:0,height:ROAD,background:'#64748b'}}/>
        {/* Center dashes */}
        <div style={{position:'absolute',top:roadTop+ROAD/2-1,left:0,right:0,height:2,backgroundImage:'repeating-linear-gradient(to right,#fcd34d 0 18px,transparent 18px 32px)',opacity:0.85}}/>
        {/* Kerb lines */}
        <div style={{position:'absolute',top:roadTop,left:0,right:0,height:2,background:'#e2e8f0',opacity:0.35}}/>
        <div style={{position:'absolute',top:roadBot-2,left:0,right:0,height:2,background:'rgba(255,255,255,0.15)'}}/>

        {/* ── Ground under road ─────────────────────── */}
        <div style={{position:'absolute',top:roadBot,left:0,right:0,bottom:0,background:'linear-gradient(to bottom,#475569,#334155)'}}/>

        {/* ── Stores ────────────────────────────────── */}
        {storeConfigs.map((s, i) => (
          <div key={i} style={{
            position:'absolute', left:`${s.pct}%`,
            bottom:storeBotFromBot, transform:'translateX(-50%)', zIndex:3,
          }}>
            <svg width="22" height="18" viewBox="0 0 22 18">
              {/* Roof (triangle) */}
              <polygon points="0,8 11,1 22,8" fill={s.roof}/>
              {/* Walls */}
              <rect x="0" y="7" width="22" height="11" rx="1.5" fill={s.wall}/>
              {/* Left window */}
              <rect x="2" y="10" width="5" height="5" rx="0.5" fill="#93c5fd" opacity="0.85"/>
              {/* Right window */}
              <rect x="15" y="10" width="5" height="5" rx="0.5" fill="#93c5fd" opacity="0.85"/>
              {/* Door */}
              <rect x="8.5" y="11" width="5" height="7" rx="0.5" fill={s.roof} opacity="0.55"/>
              {/* Sign strip */}
              <rect x="3" y="7" width="16" height="3" rx="0.5" fill={s.roof} opacity="0.7"/>
            </svg>

            {/* Price bubble — appears when car stops at this store */}
            {s.price && (
              <div style={{
                animation:`srP${i+1} ${DUR} ease-out infinite`,
                opacity:0, position:'absolute',
                bottom:20, left:'50%',
                fontSize:8.5, fontWeight:900,
                color:'#047857', background:'#d1fae5',
                border:'1.5px solid #6ee7b7', borderRadius:6,
                padding:'2px 5px', whiteSpace:'nowrap',
                zIndex:10, boxShadow:'0 2px 6px rgba(5,150,105,0.22)',
                pointerEvents:'none',
              }}>
                {s.price}
                {/* Down-arrow pointer */}
                <div style={{
                  position:'absolute', bottom:-5, left:'50%',
                  transform:'translateX(-50%)',
                  width:0, height:0,
                  borderLeft:'4px solid transparent',
                  borderRight:'4px solid transparent',
                  borderTop:'5px solid #6ee7b7',
                }}/>
              </div>
            )}
          </div>
        ))}

        {/* ── Bundly car ────────────────────────────── */}
        <div style={{
          position:'absolute', bottom:carBotFromBot, zIndex:5,
          animation:`srCar ${DUR} linear infinite`,
        }}>
          <svg width="26" height="20" viewBox="0 0 26 20">
            <defs>
              <linearGradient id="srCarGrad" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stopColor="#6d28d9"/>
                <stop offset="100%" stopColor="#a855f7"/>
              </linearGradient>
            </defs>
            {/* Body */}
            <rect x="0" y="1" width="26" height="13" rx="4" fill="url(#srCarGrad)"/>
            {/* Windshield */}
            <rect x="2" y="2.5" width="11" height="7" rx="2" fill="#a5b4fc" opacity="0.45"/>
            {/* B logo */}
            <text x="19" y="9" textAnchor="middle" dominantBaseline="middle" fontSize="8" fill="white" fontWeight="900" fontFamily="Rubik,sans-serif">B</text>
            {/* Headlights */}
            <rect x="23" y="6" width="3" height="2" rx="0.5" fill="#fef08a" opacity="0.9"/>
            {/* Wheels */}
            <circle cx="6.5"  cy="17.5" r="3" fill="#1e1b4b"/>
            <circle cx="6.5"  cy="17.5" r="1.4" fill="#818cf8"/>
            <circle cx="19.5" cy="17.5" r="3" fill="#1e1b4b"/>
            <circle cx="19.5" cy="17.5" r="1.4" fill="#818cf8"/>
          </svg>
        </div>

        {/* ── Count badge (top-right) ────────────────── */}
        <div style={{
          position:'absolute', top:7, right:10, zIndex:10,
          background:'rgba(79,70,229,0.88)', color:'white',
          borderRadius:20, padding:'2.5px 10px',
          fontSize:11, fontWeight:900,
          backdropFilter:'blur(4px)',
          boxShadow:'0 1px 6px rgba(79,70,229,0.28)',
        }}>
          {count} נמצאו
        </div>

        {/* ── Phase label (top-left) ─────────────────── */}
        <div style={{
          position:'absolute', top:8, left:10, zIndex:10,
          color:'#1e3a8a', fontSize:11, fontWeight:700,
        }}>
          {phase === 'enriching' ? '🤖 מעשיר עם AI...' : '🔍 סורק חנויות...'}
        </div>
      </div>
    </>
  );
}

// ─────────────────────────────────────────────────────────────────
//  DEAL OF THE DAY — countdown banner
// ─────────────────────────────────────────────────────────────────
// ─────────────────────────────────────────────────────────────────
//  PERSONAL RECOMMENDATIONS — "מותאם בשבילך"
//  Pulls scored deal IDs from the recommender and renders a horizontal
//  carousel above the standard deal grid. When the user has no history,
//  the server returns a popularity fallback (so the carousel is never
//  empty for new visitors).
// ─────────────────────────────────────────────────────────────────
function PersonalRecommendations({ recos, deals, onDealClick, lang }) {
  // Memoize the deal lookup map and the filtered/joined item list — without
  // this, every parent re-render rebuilds them, which becomes expensive on
  // pages with hundreds of deals.
  const dealById = useMemo(() => new Map(deals.map(d => [d.id, d])), [deals]);
  const items = useMemo(() => (
    (recos?.recommendations || [])
      .map(r => ({ ...r, deal: dealById.get(r.dealId) }))
      .filter(x => x.deal)
  ), [recos, dealById]);
  if (!recos?.recommendations?.length) return null;
  if (items.length === 0) return null;
  const isPersonalized = recos.source === "personalized";
  const profile        = recos.profile;
  return (
    <section className="mb-10">
      <div className="flex items-center gap-3 mb-5">
        <div className="w-9 h-9 rounded-xl bg-gradient-to-br from-pink-500 via-rose-500 to-fuchsia-600 flex items-center justify-center shadow-md">
          <span className="text-lg">✨</span>
        </div>
        <div className="flex-1 min-w-0">
          <h2 className="text-xl font-bold text-gray-900">{isPersonalized ? "מותאם בשבילך" : "החמות ביותר עכשיו"}</h2>
          <p className="text-xs text-gray-500">
            {isPersonalized
              ? `דירגנו את הקבוצות לפי ההתנהגות שלך באתר${profile?.topBrands?.length ? ` · אוהב ${profile.topBrands.slice(0, 2).join(", ")}` : ""}${profile?.topCategories?.length ? ` · קטגוריות ${profile.topCategories.slice(0, 2).join(", ")}` : ""}`
              : "התחל לעיין ולשמור פריטים — והמלצות אישיות יופיעו פה"}
          </p>
        </div>
      </div>
      <div className="flex gap-3 overflow-x-auto pb-3 scrollbar-none">
        {items.map(({ deal, score, reason }) => {
          const name  = deal.name?.[lang] || deal.name?.he || deal.productName || "";
          const price = deal.groupOffer || deal.marketMin || 0;
          return (
            <button
              key={deal.id}
              onClick={() => onDealClick?.(deal)}
              className="flex-shrink-0 w-56 text-right bg-white rounded-2xl border-2 border-pink-100 hover:border-pink-300 hover:shadow-lg transition overflow-hidden">
              <div className="h-32 bg-gray-50 flex items-center justify-center overflow-hidden relative">
                {deal.image
                  ? <img loading="lazy" src={deal.image} alt={name} className="max-h-full max-w-full object-contain p-2" onError={e => { e.target.style.display = "none"; }} />
                  : <span className="text-3xl">📦</span>}
                {isPersonalized && (
                  <span className="absolute top-2 right-2 text-[10px] font-black bg-pink-500 text-white px-2 py-0.5 rounded-full shadow">
                    {score}% התאמה
                  </span>
                )}
              </div>
              <div className="p-3">
                <p className="text-sm font-black text-gray-900 line-clamp-2 leading-tight mb-1">{name}</p>
                <p className="text-base font-black text-pink-700">₪{price.toLocaleString()}</p>
                <p className="text-[10px] text-gray-500 mt-1 line-clamp-1">{reason}</p>
                <div className="flex items-center gap-1 text-[10px] text-gray-400 mt-1">
                  <Users className="w-3 h-3" />
                  <span>{deal.participants || 0} מצטרפים</span>
                </div>
              </div>
            </button>
          );
        })}
      </div>
    </section>
  );
}

function DealOfTheDayBanner({ deals, lang, t, onDealClick }) {
  // Pick the hottest deal (most participants, hot:true preferred)
  const hotDeals = deals.filter(d => d.hot);
  const deal = hotDeals.length > 0
    ? hotDeals.reduce((a, b) => b.participants > a.participants ? b : a)
    : deals.reduce((a, b) => b.participants > a.participants ? b : a);

  const [countdown, setCountdown] = useState({ h: 0, m: 0, s: 0 });
  useEffect(() => {
    const target = new Date();
    target.setHours(23, 59, 59, 999);
    const tick = () => {
      const diff = Math.max(0, target - new Date());
      setCountdown({
        h: Math.floor(diff / 3600000),
        m: Math.floor((diff % 3600000) / 60000),
        s: Math.floor((diff % 60000) / 1000),
      });
    };
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, []);

  if (!deal) return null;
  const name = cleanName(deal.name[lang] || deal.name.en);
  const pad = n => String(n).padStart(2, "0");
  const bestPrice = deal.bids?.length > 0
    ? Math.min(...deal.bids.map(b => b.amount))
    : deal.groupOffer;
  const tiers = makeTiers(deal.marketMin);
  const next = nextTier(tiers, deal.participants);
  const toNext = next ? next.people - deal.participants : 0;

  return (
    <div className="relative overflow-hidden rounded-2xl mb-8 shadow-xl"
      style={{ background: "linear-gradient(135deg, #c2410c 0%, #ea580c 45%, #f97316 100%)" }}>
      {/* Decorative circles */}
      <div className="absolute -top-10 -right-10 w-40 h-40 bg-white/10 rounded-full pointer-events-none" />
      <div className="absolute -bottom-8 -left-8 w-32 h-32 bg-white/10 rounded-full pointer-events-none" />

      <div className="relative z-10 p-5 text-white">
        {/* Header */}
        <div className="flex items-center gap-2 mb-3">
          <span className="text-2xl">🔥</span>
          <span className="text-xs font-black uppercase tracking-widest bg-white/20 px-3 py-1 rounded-full">
            דיל היום
          </span>
          <span className="text-xs opacity-75 mr-auto">נסגר בעוד:</span>
          <div className="flex items-center gap-1 bg-black/30 rounded-xl px-3 py-1.5 tabular-nums font-black text-base">
            <span>{pad(countdown.h)}</span>
            <span className="opacity-60">:</span>
            <span>{pad(countdown.m)}</span>
            <span className="opacity-60">:</span>
            <span>{pad(countdown.s)}</span>
          </div>
        </div>

        {/* Content */}
        <div className="flex gap-4 items-center">
          <div className="flex-1 min-w-0">
            <h3 className="text-lg font-black mb-1 leading-tight truncate">{name}</h3>
            <div className="flex items-baseline gap-2 mb-3 flex-wrap">
              <span className="text-3xl font-black">₪{bestPrice.toLocaleString()}</span>
              <span className="text-sm line-through opacity-60">₪{deal.marketMax.toLocaleString()}</span>
              <span className="bg-white/25 text-xs font-bold px-2 py-0.5 rounded-full">
                חיסכון {deal.discount}%
              </span>
            </div>

            {/* Next tier teaser */}
            {next && (
              <p className="text-xs bg-white/20 rounded-xl px-3 py-1.5 mb-3 font-semibold inline-block">
                🎯 עוד {toNext} קונים → מחיר יורד ל-₪{next.price.toLocaleString()}!
              </p>
            )}

            {/* Progress bar */}
            <div className="flex items-center gap-2 mb-3">
              <div className="flex-1 bg-white/20 rounded-full h-2 overflow-hidden">
                <div className="h-full bg-white rounded-full transition-all"
                  style={{ width: `${Math.round((deal.participants / deal.maxParticipants) * 100)}%` }} />
              </div>
              <span className="text-xs font-semibold whitespace-nowrap">
                {deal.participants} / {deal.maxParticipants} קונים
              </span>
            </div>

            <button
              onClick={() => onDealClick(deal)}
              className="bg-white text-orange-600 font-black text-sm px-6 py-2.5 rounded-xl hover:bg-orange-50 transition shadow-sm active:scale-95">
              הצטרף עכשיו →
            </button>
          </div>

          {/* Product image */}
          <ProductImage
            query={deal.name.en}
            fallback={deal.image}
            alt={name}
            className="w-28 h-28 rounded-2xl flex-shrink-0 hidden sm:flex overflow-hidden"
            imgClassName="w-28 h-28 object-contain bg-white/10 rounded-2xl opacity-90 shadow-lg p-1"
          />
        </div>
      </div>
    </div>
  );
}

