// Hebrew plural → singular normalization. Applied per word so multi-word
// category names like "מדיחי כלים" each get stemmed individually.
function singularizeHebrew(text) {
  if (!text) return "";
  return text
    .split(/\s+/)
    .map(w => {
      if (w.length <= 3) return w;
      if (w.endsWith("ים")) return w.slice(0, -2);     // מקררים → מקרר
      if (w.endsWith("ות") && w.length >= 5) return w.slice(0, -2); // מסחטות → מסחט
      return w;
    })
    .join(" ");
}

// Extract a budget ceiling from a wizard searchTerm if it contains a price
// range (e.g. "budget under 2000 ILS" → 2000). Returns 0 if no match.
function extractBudgetFromSearchTerm(term) {
  if (!term) return 0;
  const m = String(term).match(/\b(\d{3,6})\b/);
  return m ? parseInt(m[1], 10) : 0;
}

// Returns true if a string is mostly Hebrew letters.
const isHebrew = (s) => /[\u0590-\u05FF]/.test(s);

// Build /api/catalog-search query + structured filters from base name + criteria.
// Returns: { q, priceMax, softFilters }
//   q          — short Hebrew query used by catalog-search (just the base name)
//   priceMax   — server-applied price ceiling
//   softFilters — array of Hebrew strings that should ideally appear in the
//                 product name. Used client-side for RANKING (not hard filtering)
//                 so we show matching products first without losing coverage.
function buildBundleQuery(baseName, criteria, values) {
  const q = singularizeHebrew(baseName);
  let priceMax = 0;
  const softFilters = [];

  for (const field of criteria) {
    const v = values[field.key];
    if (!v) continue; // empty = "תציע לי"

    // Budget — extract numeric ceiling from value or wizard searchTerm
    if (field.key === "budget" || /budget|תקציב|מחיר/.test(field.label || "")) {
      const opt = (field.options || []).find(o => o.value === v);
      let ceiling = 0;
      if (opt?.searchTerm) ceiling = extractBudgetFromSearchTerm(opt.searchTerm);
      if (!ceiling) ceiling = parseInt(v, 10) || 0;
      if (ceiling > 0) priceMax = ceiling;
      continue;
    }

    // Look up the full option object for wizard criteria
    const opt = (field.options || []).find(o => o.value === v);

    // Prefer the Hebrew label for matching — it's what appears in product names.
    // English searchTerms ("top freezer") almost never match Hebrew names ("מקפיא עליון").
    let softTerm = "";
    if (opt?.label && isHebrew(opt.label)) {
      softTerm = opt.label;
    } else if (isHebrew(String(v))) {
      softTerm = String(v);
    } else if (opt?.searchTerm && isHebrew(opt.searchTerm)) {
      softTerm = opt.searchTerm;
    }

    // Collect individual words from the soft term — skip stop-words and
    // common filler that would match nothing useful.
    if (softTerm) {
      const STOP = new Set(["לי","את","עם","של","ללא","יותר","פחות","עד","או","גדול","קטן","בינוני","ממוצע","לא","משנה","כל","הכל"]);
      const words = softTerm
        .replace(/["']/g, "")
        .split(/[\s,/+]+/)
        .map(w => w.trim())
        .filter(w => w.length >= 2 && !STOP.has(w) && !/^\d+$/.test(w));
      for (const w of words) {
        if (!softFilters.includes(w)) softFilters.push(w);
      }
    }
  }

  return { q, priceMax, softFilters };
}

function ProductPickerForBundle({ onAddProduct, onClose, onViewFullDetails }) {
  // stage: "browse" | "criteria" | "results"
  const [stage, setStage] = useState("browse");
  const [level, setLevel] = useState(0); // 0=main cats, 1=sub-cats, 2=items
  const [selectedCat, setSelectedCat] = useState(null);
  const [selectedSub, setSelectedSub] = useState(null);
  const [selectedItem, setSelectedItem] = useState(null);
  const [freeSearchInput, setFreeSearchInput] = useState("");
  const [criteriaBase, setCriteriaBase] = useState(""); // Display name for current criteria step
  const [criteriaFields, setCriteriaFields] = useState([]);
  const [criteriaValues, setCriteriaValues] = useState({});
  const [addedItems, setAddedItems] = useState([]);
  const [detailProduct, setDetailProduct] = useState(null); // product object when detail modal is open

  // Free-search autocomplete state (live suggestions from /api/search-products)
  const [autoSuggestions, setAutoSuggestions] = useState([]);
  const [autoLoading, setAutoLoading] = useState(false);
  const autoAbortRef = useRef(null);

  // Criteria-form search state
  const [searching, setSearching] = useState(false);
  const [searchResults, setSearchResults] = useState([]);
  const [searchError, setSearchError] = useState(null);
  const [lastQuery, setLastQuery] = useState("");

  const handleMainCat = (cat) => {
    setSelectedCat(cat); setSelectedSub(null); setSelectedItem(null); setLevel(1);
  };

  // User picked a sub-category → show specific items list (level 2).
  // If the sub has only ONE item (a passthrough — used for categories like
  // "מסכי מחשב" where the per-screen-size breakdown is redundant once the
  // results-page filter chips exist), jump straight to the search criteria
  // for that item without rendering the level-2 button page.
  const handleSub = (sub) => {
    setSelectedSub(sub);
    setSelectedItem(null);
    if (sub.items?.length === 1) {
      handleItem(sub.items[0]);
    } else {
      setLevel(2);
    }
  };

  // User picked a specific item → advance to criteria form
  const handleItem = (itemName) => {
    setSelectedItem(itemName);
    startCriteria(itemName);
  };

  // Live autocomplete: debounced fetch from local catalog (instant, no external calls)
  useEffect(() => {
    const term = freeSearchInput.trim();
    if (term.length < 2) {
      setAutoSuggestions([]);
      setAutoLoading(false);
      return;
    }
    if (autoAbortRef.current) autoAbortRef.current.abort();
    const ctrl = new AbortController();
    autoAbortRef.current = ctrl;
    setAutoLoading(true);
    const t = setTimeout(async () => {
      try {
        const r = await fetch(`/api/catalog-search?q=${encodeURIComponent(term)}&limit=12`, { signal: ctrl.signal });
        if (!r.ok) throw new Error("שגיאה");
        const data = await r.json();
        // Normalise to picker shape: name / image / priceAvg / priceMin
        const suggestions = (data.products || []).map(p => ({
          nameHe:    p.name,
          image:     p.image,
          priceAvg:  p.price,
          priceMin:  p.price,
          slug:      p.slug,
          id:        p.id,
        }));
        setAutoSuggestions(suggestions);
      } catch (e) {
        if (e.name !== "AbortError") setAutoSuggestions([]);
      } finally {
        if (!ctrl.signal.aborted) setAutoLoading(false);
      }
    }, 250);
    return () => { clearTimeout(t); ctrl.abort(); };
  }, [freeSearchInput]);

  // Load wizard questions from the SAME /api/wizard-questions endpoint the
  // main screen uses — GPT-generated, category-aware questions with chip
  // options and search terms. Higher quality than hardcoded criteria.
  const [wizardLoading, setWizardLoading] = useState(false);

  const startCriteria = async (baseName) => {
    setCriteriaBase(baseName);
    setCriteriaFields([]);
    setCriteriaValues({});
    setSearchResults([]);
    setSearchError(null);
    setLastQuery("");
    setStage("criteria");
    setWizardLoading(true);
    try {
      const r = await fetch(`/api/wizard-questions?q=${encodeURIComponent(baseName)}`);
      if (!r.ok) throw new Error("שגיאה בטעינת שאלות");
      const data = await r.json();
      // Normalise wizard questions to the same shape criteriaFields expects,
      // plus keep the full option objects so we can use `searchTerm` when building the query.
      const wizardFields = (data.questions || []).map(q => ({
        key:     q.id,
        label:   q.label,
        sublabel:q.sublabel || "",
        icon:    q.icon || "",
        type:    "wizard",
        options: [
          ANY_OPTION,
          ...(q.options || []).map(o => ({
            value:      o.value,
            label:      o.label,
            searchTerm: o.searchTerm || "",
            icon:       o.icon || "",
            desc:       o.desc || "",
          })),
        ],
      }));
      // Fallback: if wizard returned nothing, fall back to hardcoded criteria
      setCriteriaFields(wizardFields.length > 0 ? wizardFields : getBundleCriteriaFor(baseName));
    } catch (_) {
      // On error, use hardcoded criteria as fallback so the user can still filter
      setCriteriaFields(getBundleCriteriaFor(baseName));
    } finally {
      setWizardLoading(false);
    }
  };

  // Run search with whatever criteria are set (all fields have a "תציע לי" fallback)
  const runCriteriaSearch = async () => {
    setSearchError(null);
    const { q, priceMax, softFilters } = buildBundleQuery(criteriaBase, criteriaFields, criteriaValues);
    if (!q || q.length < 2) {
      setSearchError("חיפוש קצר מדי");
      return;
    }
    setSearching(true);
    setStage("results");
    setLastQuery(q);
    try {
      // Restrict the search to the exact product-db slug for this item, if known.
      // This is the single most important fix — searching "כיריים" inside the
      // `hobs` slug will NEVER return "תנור משולב כיריים" (which lives in `ovens`).
      const slug = BUNDLE_ITEM_TO_SLUG[criteriaBase] || null;
      const slugParam = slug ? `&slug=${encodeURIComponent(slug)}` : "";

      const r = await fetch(`/api/catalog-search?q=${encodeURIComponent(q)}&limit=50${slugParam}`);
      if (!r.ok) throw new Error("שגיאה בחיפוש");
      const data = await r.json();
      let products = (data.products || []).map(p => ({
        nameHe:   p.name,
        image:    p.image,
        priceAvg: p.price,
        priceMin: p.price,
        id:       p.id,
        slug:     p.slug,
        manufacturer: p.manufacturer || null,
      }));

      // Price filter (products without a price are excluded when budget is set
      // — since we can't verify they fit the budget).
      if (priceMax > 0) {
        products = products.filter(p => p.priceAvg > 0 && p.priceAvg <= priceMax);
      }

      // Rank by soft filter matches: products whose name contains more of the
      // Hebrew filter terms (like "מקפיא עליון", "אינדוקציה") come first.
      if (softFilters.length > 0) {
        products = products.map(p => {
          const name = (p.nameHe || "").toLowerCase();
          const matches = softFilters.filter(t => name.includes(t.toLowerCase())).length;
          return { ...p, _softScore: matches };
        });
        // Sort: higher softScore first, then by price asc
        products.sort((a, b) => {
          if (b._softScore !== a._softScore) return b._softScore - a._softScore;
          return (a.priceAvg || 999999) - (b.priceAvg || 999999);
        });
      } else {
        // No soft filters → sort purely by price ascending
        products.sort((a, b) => (a.priceAvg || 999999) - (b.priceAvg || 999999));
      }

      setSearchResults(products);
    } catch (e) {
      setSearchError(e.message);
    } finally {
      setSearching(false);
    }
  };

  const handleAddItem = (item) => {
    const name = typeof item === "string" ? item : (item.nameHe || item.nameEn || item.name || "");
    if (!name) return;
    const product = typeof item === "string"
      ? { name, image: "", marketPrice: 0 }
      : {
          name,
          image: item.image || "",
          marketPrice: item.priceAvg || item.priceMin || item.marketPrice || 0,
        };
    onAddProduct(product);
    setAddedItems(prev => [...prev, name]);
  };

  const goBack = () => {
    if (stage === "results") { setStage("criteria"); return; }
    if (stage === "criteria") {
      // Return to items list (level 2) if we came from there, else to browse
      setStage("browse");
      setSelectedItem(null);
      return;
    }
    if (level === 2) { setLevel(1); setSelectedSub(null); return; }
    if (level === 1) { setLevel(0); setSelectedCat(null); }
  };

  const isAdded = (name) => addedItems.includes(name);

  const showBack = stage !== "browse" || level > 0;
  const headerTitle =
    stage === "criteria" ? `סינון: ${criteriaBase}` :
    stage === "results"  ? `תוצאות: ${lastQuery}` :
    level === 2          ? selectedSub?.name :
    level === 1          ? selectedCat?.name :
    "הוסף מוצר לחבילה";

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[60] flex items-end sm:items-center justify-center p-4" onClick={onClose}>
      <div className="bg-white rounded-t-3xl sm:rounded-3xl shadow-2xl w-full max-w-lg max-h-[85vh] flex flex-col overflow-hidden" onClick={e => e.stopPropagation()}>

        {/* Header */}
        <div className="bg-gradient-to-r from-indigo-600 to-violet-600 px-5 py-4 flex items-center justify-between flex-shrink-0">
          <div className="flex items-center gap-3">
            {showBack && (
              <button onClick={goBack} className="w-7 h-7 flex items-center justify-center rounded-lg bg-white/20 hover:bg-white/30 transition text-white">
                <svg xmlns="http://www.w3.org/2000/svg" className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
              </button>
            )}
            <h2 className="font-black text-base text-white">{headerTitle}</h2>
          </div>
          <button onClick={onClose} className="w-7 h-7 flex items-center justify-center rounded-lg bg-white/20 hover:bg-white/30 transition text-white">
            <X className="w-3.5 h-3.5" />
          </button>
        </div>

        {/* Added count badge */}
        {addedItems.length > 0 && (
          <div className="px-5 py-2 bg-emerald-50 border-b border-emerald-100 flex items-center gap-2 flex-shrink-0">
            <BadgeCheck className="w-4 h-4 text-emerald-500" />
            <span className="text-xs font-bold text-emerald-700">{addedItems.length} מוצרים נוספו לחבילה</span>
          </div>
        )}

        {/* Content */}
        <div className="overflow-y-auto flex-1 p-5">

          {/* ── STAGE: BROWSE ── */}
          {stage === "browse" && (
            <>
              {/* Free text search with autocomplete */}
              <div className="mb-4 p-4 bg-gradient-to-br from-indigo-50 to-violet-50 border-2 border-indigo-100 rounded-2xl">
                <p className="text-xs font-bold text-indigo-700 mb-2 flex items-center gap-1.5">
                  <Search className="w-3.5 h-3.5" /> חפש מוצר מהאתר
                </p>
                <div className="relative">
                  <input
                    type="text"
                    value={freeSearchInput}
                    onChange={e => setFreeSearchInput(e.target.value)}
                    placeholder="התחל להקליד... (מקרר Samsung, iPhone, Sony...)"
                    className="w-full px-3 py-2.5 bg-white border border-indigo-200 rounded-xl text-sm focus:outline-none focus:border-indigo-400 text-right" dir="rtl"
                  />
                  {autoLoading && (
                    <div className="absolute left-3 top-1/2 -translate-y-1/2">
                      <Loader2 className="w-4 h-4 animate-spin text-indigo-400" />
                    </div>
                  )}
                </div>

                {/* Autocomplete dropdown */}
                {freeSearchInput.trim().length >= 2 && !autoLoading && (
                  <div className="mt-2 bg-white rounded-xl border border-indigo-100 shadow-sm max-h-72 overflow-y-auto">
                    {autoSuggestions.length === 0 ? (
                      <div className="p-4 text-center">
                        <p className="text-xs text-gray-400">לא נמצאו מוצרים. נסה מילת חיפוש אחרת.</p>
                      </div>
                    ) : (
                      autoSuggestions.map((p, i) => {
                        const name = p.nameHe || p.nameEn || "";
                        const price = p.priceAvg || p.priceMin || 0;
                        const already = isAdded(name);
                        return (
                          <button
                            key={i}
                            type="button"
                            disabled={already}
                            onClick={() => { handleAddItem(p); setFreeSearchInput(""); }}
                            className={`w-full flex items-center gap-3 p-2.5 text-right border-b border-gray-50 last:border-0 transition ${
                              already ? "opacity-50 cursor-not-allowed" : "hover:bg-indigo-50"
                            }`}
                          >
                            {p.image ? (
                              <img src={p.image} alt={name}
                                className="w-10 h-10 rounded-lg object-contain bg-gray-50 border border-gray-100 flex-shrink-0"
                                onError={e => { e.target.style.display = "none"; }} />
                            ) : (
                              <div className="w-10 h-10 rounded-lg bg-gradient-to-br from-indigo-50 to-violet-50 flex items-center justify-center flex-shrink-0">
                                <Package className="w-5 h-5 text-indigo-200" />
                              </div>
                            )}
                            <div className="flex-1 min-w-0">
                              <p className="text-xs font-bold text-gray-800 line-clamp-2 leading-tight">{name}</p>
                              {price > 0 && (
                                <p className="text-[10px] text-indigo-600 font-bold mt-0.5">₪{price.toLocaleString()}</p>
                              )}
                            </div>
                            {already ? (
                              <BadgeCheck className="w-4 h-4 text-emerald-500 flex-shrink-0" />
                            ) : (
                              <Plus className="w-4 h-4 text-indigo-500 flex-shrink-0" />
                            )}
                          </button>
                        );
                      })
                    )}
                  </div>
                )}

                {freeSearchInput.trim().length < 2 && (
                  <p className="text-[10px] text-gray-500 mt-2">חייב לבחור מוצר מתוך הרשימה — לא ניתן להקליד מוצר שלא קיים באתר</p>
                )}
              </div>

              {/* Divider */}
              <div className="flex items-center gap-3 my-4">
                <div className="flex-1 h-px bg-gray-200" />
                <span className="text-[10px] text-gray-400 font-bold">או דפדף לפי קטגוריה (עם סינון)</span>
                <div className="flex-1 h-px bg-gray-200" />
              </div>

              {/* Level 0 — Main categories */}
              {level === 0 && (
                <div className="grid grid-cols-2 gap-3">
                  {CATEGORY_TREE.map((cat) => (
                    <button key={cat.id} onClick={() => handleMainCat(cat)}
                      className={`flex flex-col items-center gap-2 p-4 ${cat.bg} ${cat.border} border-2 rounded-2xl hover:shadow-md transition-all group hover:scale-105 active:scale-95`}>
                      <div className={`w-12 h-12 rounded-xl bg-gradient-to-br ${cat.color} flex items-center justify-center shadow-sm`}>
                        <span className="text-xl">{cat.icon}</span>
                      </div>
                      <span className="text-xs font-bold text-gray-800 text-center leading-tight">{cat.name}</span>
                      <span className="text-[9px] text-gray-400">{cat.sub.length} תתי קטגוריות</span>
                    </button>
                  ))}
                </div>
              )}

              {/* Level 1 — Sub-categories */}
              {level === 1 && selectedCat && (
                <div className="grid grid-cols-1 gap-2">
                  {selectedCat.sub.map((sub, i) => (
                    <button key={i} onClick={() => handleSub(sub)}
                      className={`flex items-center gap-3 p-3.5 ${selectedCat.bg} ${selectedCat.border} border rounded-xl hover:shadow-md transition-all group text-right`}>
                      <div className={`w-9 h-9 rounded-lg bg-gradient-to-br ${selectedCat.color} flex items-center justify-center flex-shrink-0`}>
                        <span className="text-base">{sub.icon}</span>
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="text-sm font-bold text-gray-800">{sub.name}</div>
                        <div className="text-[10px] text-gray-400">{sub.items.length} מוצרים</div>
                      </div>
                      <svg xmlns="http://www.w3.org/2000/svg" className="w-4 h-4 text-gray-300 flex-shrink-0 rotate-180" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
                    </button>
                  ))}
                </div>
              )}

              {/* Level 2 — Specific items (e.g. "מקררים", "מקפיאים") */}
              {level === 2 && selectedCat && selectedSub && (
                <div className="grid grid-cols-2 gap-2">
                  {selectedSub.items.map((item, i) => (
                    <button key={i} onClick={() => handleItem(item)}
                      className={`flex items-center justify-between gap-2 p-3 ${selectedCat.bg} ${selectedCat.border} border rounded-xl hover:shadow-md transition-all text-right`}>
                      <span className="text-xs font-bold text-gray-800 leading-tight flex-1">{item}</span>
                      <svg xmlns="http://www.w3.org/2000/svg" className="w-3.5 h-3.5 text-gray-300 flex-shrink-0 rotate-180" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
                    </button>
                  ))}
                </div>
              )}
            </>
          )}

          {/* ── STAGE: CRITERIA FORM ── */}
          {stage === "criteria" && (
            <div className="space-y-4">
              <div className="bg-indigo-50 border border-indigo-200 rounded-2xl p-3 flex items-center gap-2">
                <Tag className="w-4 h-4 text-indigo-500 flex-shrink-0" />
                <p className="text-xs text-indigo-700 flex-1">
                  {wizardLoading ? "טוען שאלות חכמות..." : "צמצם את החיפוש — בחר מאפיינים שמתאימים לך. לא צריך דגם ספציפי."}
                </p>
              </div>

              {wizardLoading && (
                <div className="flex justify-center py-10">
                  <Loader2 className="w-6 h-6 animate-spin text-indigo-500" />
                </div>
              )}

              {!wizardLoading && criteriaFields.map((field) => (
                <div key={field.key}>
                  <label className="block text-xs font-bold text-gray-700 mb-2 flex items-center gap-1.5">
                    {field.icon && <span className="text-base">{field.icon}</span>}
                    <span>{field.label}</span>
                  </label>
                  {field.sublabel && <p className="text-[10px] text-gray-400 mb-2 -mt-1">{field.sublabel}</p>}
                  <div className="grid grid-cols-3 gap-2">
                    {field.options.map((opt) => {
                      const isSel = criteriaValues[field.key] === opt.value;
                      const isAny = opt.value === "";
                      return (
                        <button
                          key={opt.value || "_any"}
                          type="button"
                          onClick={() => setCriteriaValues(v => ({ ...v, [field.key]: opt.value }))}
                          title={opt.desc || ""}
                          className={`py-2 px-2 rounded-xl text-xs font-bold border-2 transition ${
                            isSel
                              ? isAny
                                ? "bg-gray-500 text-white border-gray-500 shadow-sm"
                                : "bg-indigo-600 text-white border-indigo-600 shadow-sm"
                              : isAny
                                ? "bg-gray-50 text-gray-500 border-dashed border-gray-300 hover:border-gray-400"
                                : "bg-white text-gray-700 border-gray-200 hover:border-indigo-300"
                          }`}
                        >
                          {opt.label}
                        </button>
                      );
                    })}
                  </div>
                </div>
              ))}

              {searchError && (
                <div className="bg-red-50 border border-red-200 rounded-xl p-2 text-center">
                  <p className="text-xs font-bold text-red-600">{searchError}</p>
                </div>
              )}

              <button
                onClick={runCriteriaSearch}
                className="w-full py-3 bg-gradient-to-r from-indigo-600 to-violet-600 hover:from-indigo-700 hover:to-violet-700 text-white font-black rounded-xl text-sm transition flex items-center justify-center gap-2">
                <Search className="w-4 h-4" /> חפש מוצרים לפי הסינון
              </button>
            </div>
          )}

          {/* ── STAGE: RESULTS ── */}
          {stage === "results" && (
            <div>
              {searching && (
                <div className="text-center py-10">
                  <Loader2 className="w-6 h-6 animate-spin text-indigo-500 mx-auto mb-2" />
                  <p className="text-xs text-gray-500">מחפש מוצרים אמיתיים מהאתר...</p>
                </div>
              )}

              {!searching && searchError && (
                <div className="text-center py-8">
                  <p className="text-sm font-bold text-red-500 mb-3">{searchError}</p>
                  <button onClick={() => setStage("criteria")}
                    className="bg-indigo-600 text-white px-5 py-2 rounded-xl text-xs font-bold hover:bg-indigo-700 transition">
                    חזור לסינון
                  </button>
                </div>
              )}

              {!searching && !searchError && searchResults.length === 0 && (
                <div className="text-center py-10">
                  <p className="text-3xl mb-2">🔍</p>
                  <p className="text-sm font-bold text-gray-700 mb-1">לא נמצאו תוצאות עבור "{lastQuery}"</p>
                  <p className="text-xs text-gray-400 mb-4">נסה סינון שונה או הוסף ידנית</p>
                  <div className="flex gap-2 justify-center">
                    <button onClick={() => setStage("criteria")}
                      className="bg-indigo-100 text-indigo-700 px-4 py-2 rounded-xl text-xs font-bold hover:bg-indigo-200 transition">
                      שנה סינון
                    </button>
                    <button onClick={() => handleAddItem(lastQuery)}
                      className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-xs font-bold hover:bg-indigo-700 transition flex items-center gap-1">
                      <Plus className="w-3.5 h-3.5" /> הוסף "{criteriaBase}" ידנית
                    </button>
                  </div>
                </div>
              )}

              {!searching && !searchError && searchResults.length > 0 && (
                <>
                  <p className="text-xs text-gray-500 mb-3 font-semibold">
                    {searchResults.length} מוצרים — לחץ על "פרטי המוצר" לפרטים מלאים
                  </p>
                  <div className="space-y-2.5">
                    {searchResults.map((p, i) => {
                      const name = p.nameHe || p.nameEn || "";
                      const price = p.priceAvg || p.priceMin || 0;
                      const minPrice = p.priceMin || 0;
                      const imgSrc = p.image;
                      return (
                        <div key={i} className="flex items-center gap-3 p-3 bg-gray-50 border border-gray-100 rounded-xl">
                          {/* Larger image thumbnail */}
                          <div className="w-20 h-20 rounded-xl bg-white border border-gray-100 flex-shrink-0 overflow-hidden flex items-center justify-center">
                            {imgSrc ? (
                              <img src={imgSrc} alt={name}
                                className="max-w-full max-h-full object-contain p-1"
                                onError={e => {
                                  e.target.style.display = "none";
                                  if (e.target.parentElement) {
                                    e.target.parentElement.classList.add("bg-gradient-to-br","from-indigo-50","to-violet-50");
                                  }
                                }} />
                            ) : (
                              <Package className="w-8 h-8 text-indigo-200" />
                            )}
                          </div>

                          {/* Name + price */}
                          <div className="flex-1 min-w-0 text-right">
                            <p className="text-xs font-bold text-gray-800 line-clamp-2 leading-tight mb-1">{name}</p>
                            {price > 0 && (
                              <p className="text-[11px] text-indigo-600 font-bold">
                                ₪{price.toLocaleString()}
                              </p>
                            )}
                            {/* "פרטי המוצר" button */}
                            <button
                              onClick={() => setDetailProduct(p)}
                              className="mt-1.5 inline-flex items-center gap-1 text-[10px] font-bold text-indigo-600 bg-indigo-50 hover:bg-indigo-100 px-2.5 py-1 rounded-lg border border-indigo-100 transition"
                            >
                              <Search className="w-3 h-3" /> פרטי המוצר
                            </button>
                          </div>

                          {/* Add badge */}
                          {isAdded(name) && (
                            <span className="flex items-center gap-1 text-[10px] font-bold text-emerald-600 bg-emerald-50 px-2 py-1 rounded-lg flex-shrink-0 self-start">
                              <BadgeCheck className="w-3 h-3" /> נוסף
                            </span>
                          )}
                        </div>
                      );
                    })}
                  </div>
                </>
              )}
            </div>
          )}
        </div>

        {/* Footer — done button */}
        <div className="px-5 py-3 border-t border-gray-100 flex-shrink-0">
          <button onClick={onClose}
            className="w-full py-2.5 bg-gray-100 hover:bg-gray-200 text-gray-700 font-bold rounded-xl text-sm transition">
            {addedItems.length > 0 ? `סיום (${addedItems.length} נוספו)` : "סגור"}
          </button>
        </div>
      </div>

      {/* ── Product Detail Modal ── */}
      {detailProduct && (() => {
        const p    = detailProduct;
        const name = p.nameHe || p.nameEn || p.name || "";
        const price = p.priceAvg || p.priceMin || p.price || 0;
        const minP  = p.priceMin || 0;
        const maxP  = p.priceMax || 0;
        const img   = p.image;
        const already = isAdded(name);
        return (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[70] flex items-end sm:items-center justify-center p-4"
               onClick={(e) => { e.stopPropagation(); setDetailProduct(null); }}>
            <div className="bg-white rounded-t-3xl sm:rounded-3xl shadow-2xl w-full max-w-md max-h-[90vh] flex flex-col overflow-hidden"
                 onClick={e => e.stopPropagation()}>

              {/* Header with close */}
              <div className="flex items-center justify-between px-5 py-3 border-b border-gray-100 flex-shrink-0">
                <h3 className="font-black text-sm text-gray-800">פרטי המוצר</h3>
                <button onClick={() => setDetailProduct(null)}
                  className="w-7 h-7 flex items-center justify-center rounded-lg bg-gray-100 hover:bg-gray-200 transition">
                  <X className="w-3.5 h-3.5 text-gray-600" />
                </button>
              </div>

              {/* Scrollable body */}
              <div className="flex-1 overflow-y-auto p-5 space-y-4">
                {/* Large image */}
                <div className="w-full h-52 rounded-2xl bg-white border border-gray-100 overflow-hidden flex items-center justify-center">
                  {img ? (
                    <img src={img} alt={name}
                      className="max-w-full max-h-full object-contain p-3"
                      onError={e => {
                        e.target.style.display = "none";
                        if (e.target.parentElement) {
                          e.target.parentElement.classList.add("bg-gradient-to-br","from-indigo-50","to-violet-50");
                        }
                      }} />
                  ) : (
                    <div className="bg-gradient-to-br from-indigo-50 to-violet-50 w-full h-full flex items-center justify-center">
                      <Package className="w-16 h-16 text-indigo-200" />
                    </div>
                  )}
                </div>

                {/* Name */}
                <div>
                  <h2 className="font-black text-base text-gray-900 leading-snug">{name}</h2>
                  {p.manufacturer && (
                    <p className="text-xs text-gray-500 mt-1">יצרן: <span className="font-bold text-gray-700">{p.manufacturer}</span></p>
                  )}
                </div>

                {/* Price box */}
                {price > 0 && (
                  <div className="bg-gradient-to-br from-indigo-50 to-violet-50 border border-indigo-100 rounded-2xl p-4">
                    <p className="text-[10px] font-bold text-indigo-500 mb-1">מחיר שוק</p>
                    <p className="text-2xl font-black text-indigo-700">₪{price.toLocaleString()}</p>
                    {minP > 0 && maxP > 0 && minP !== maxP && (
                      <p className="text-[11px] text-indigo-400 mt-1">
                        טווח: ₪{minP.toLocaleString()} – ₪{maxP.toLocaleString()}
                      </p>
                    )}
                  </div>
                )}

                {/* Metadata */}
                <div className="bg-gray-50 rounded-2xl p-3 space-y-2 text-xs">
                  {p.slug && (
                    <div className="flex justify-between">
                      <span className="text-gray-500">קטגוריה:</span>
                      <span className="font-bold text-gray-800">{p.slug}</span>
                    </div>
                  )}
                  {p.id && (
                    <div className="flex justify-between">
                      <span className="text-gray-500">מזהה מוצר:</span>
                      <span className="font-mono text-gray-600 text-[10px]">{p.id}</span>
                    </div>
                  )}
                </div>

                <p className="text-[11px] text-gray-400 text-center">
                  לחץ "הוסף לחבילה שלי" למטה כדי לצרף את המוצר לחבילה הנוכחית שלך.
                </p>
              </div>

              {/* Bottom CTA — view full details + add to bundle */}
              <div className="border-t border-gray-100 p-4 flex-shrink-0 space-y-2">
                {onViewFullDetails && (
                  <button
                    onClick={async () => {
                      setDetailProduct(null);
                      await onViewFullDetails(name);
                    }}
                    className="w-full py-2.5 border-2 border-indigo-200 text-indigo-700 hover:bg-indigo-50 font-bold rounded-2xl text-sm transition flex items-center justify-center gap-2"
                  >
                    <Search className="w-4 h-4" /> פרטים נוספים והצטרפות לקבוצה
                  </button>
                )}
                {already ? (
                  <div className="w-full py-3 bg-emerald-50 border-2 border-emerald-200 text-emerald-700 font-black rounded-2xl text-sm flex items-center justify-center gap-2">
                    <BadgeCheck className="w-5 h-5" /> כבר בחבילה שלך
                  </div>
                ) : (
                  <button
                    onClick={() => { handleAddItem(p); setDetailProduct(null); }}
                    className="w-full py-3.5 bg-gradient-to-r from-indigo-600 to-violet-600 hover:from-indigo-700 hover:to-violet-700 text-white font-black rounded-2xl text-sm transition shadow-lg shadow-indigo-200/50 active:scale-[0.98] flex items-center justify-center gap-2"
                  >
                    <Plus className="w-4 h-4" /> הוסף לחבילה שלי
                  </button>
                )}
              </div>
            </div>
          </div>
        );
      })()}
    </div>
  );
}

function BundleDetailModal({ bundle, onClose, onJoin, onSave, onEdit, isSaved, onViewFullDetails }) {
  // Edit is always active — use local products state that auto-syncs to parent via onEdit
  const [prods, setProds] = useState(bundle.products);
  const totalMarket = prods.reduce((s, p) => s + (p.marketPrice || 0), 0);
  const bundlePrice = Math.round(totalMarket * 0.76);
  const savePct = totalMarket > 0 ? Math.round(((totalMarket - bundlePrice) / totalMarket) * 100) : 0;
  const progress = Math.round((bundle.participants / bundle.maxParticipants) * 100);
  const [joined, setJoined] = useState(false);
  const [saved, setSaved] = useState(isSaved);
  const [showPicker, setShowPicker] = useState(false);

  // Persist any product list change to parent (fires on add/remove).
  // Accepts an array OR a functional updater to avoid stale-closure issues
  // when multiple adds fire before React re-renders.
  const persistProds = (updater) => {
    setProds(prev => {
      const next = typeof updater === "function" ? updater(prev) : updater;
      const newMarket = next.reduce((s, p) => s + (p.marketPrice || 0), 0);
      onEdit?.(bundle, next, newMarket, Math.round(newMarket * 0.76));
      return next;
    });
  };

  const handleRemoveProduct = (idx) => {
    persistProds(prev => {
      const next = [...prev];
      next.splice(idx, 1);
      return next;
    });
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-end sm:items-center justify-center" onClick={onClose}>
      <div className="bg-white w-full max-w-xl max-h-[90vh] overflow-y-auto rounded-t-3xl sm:rounded-3xl shadow-2xl" onClick={e => e.stopPropagation()}>
        {/* Header image collage */}
        <div className="relative h-44 flex overflow-hidden rounded-t-3xl sm:rounded-t-3xl">
          {prods.slice(0, 4).map((p, i) => (
            <div key={i} className="flex-1 relative border-l first:border-l-0 border-white/30">
              {p.image ? (
                <img src={p.image} alt={p.name} className="w-full h-full object-cover" />
              ) : (
                <div className="w-full h-full bg-gray-200 flex items-center justify-center text-2xl">{bundle.icon}</div>
              )}
              <div className="absolute inset-0 bg-gradient-to-t from-black/50 to-transparent" />
            </div>
          ))}
          <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent" />
          <div className="absolute bottom-4 right-4 text-white">
            <p className="text-2xl font-black drop-shadow-lg">{bundle.title}</p>
            <p className="text-sm opacity-90">{bundle.subtitle}</p>
          </div>
          {/* Close / Fav / Edit buttons */}
          <button onClick={onClose} className="absolute top-3 left-3 w-8 h-8 bg-black/30 backdrop-blur rounded-full flex items-center justify-center text-white hover:bg-black/50 transition">
            <X className="w-4 h-4" />
          </button>
          <div className="absolute top-3 right-3 flex items-center gap-2">
            <button onClick={() => { setSaved(!saved); onSave?.(bundle, !saved); }}
              className={`w-8 h-8 backdrop-blur rounded-full flex items-center justify-center transition shadow ${saved ? "bg-red-500 text-white" : "bg-black/30 text-white hover:bg-black/50"}`}>
              <Heart className="w-4 h-4" fill={saved ? "currentColor" : "none"} />
            </button>
            {savePct > 0 && (
              <div className="bg-red-500 text-white text-xs font-black px-3 py-1 rounded-full shadow-lg">
                -{savePct}% מהשוק
              </div>
            )}
          </div>
        </div>

        <div className="p-5 space-y-5">

          {/* Stats row */}
          <div className={`${bundle.bg} ${bundle.border} border rounded-2xl p-4`}>
            <div className="flex items-center gap-3 mb-2">
              <span className="text-2xl">{bundle.icon}</span>
              <div>
                <p className="text-sm font-black text-gray-900">למה כדאי לקנות חבילה?</p>
                <p className="text-xs text-gray-600">ספקים מעדיפים למכור סט שלם — ולכן נותנים הנחה נוספת</p>
              </div>
            </div>
            <div className="grid grid-cols-3 gap-2 mt-3">
              <div className="bg-white rounded-xl p-2 text-center border border-gray-100">
                <p className="text-lg font-black text-indigo-600">{prods.length}</p>
                <p className="text-[9px] text-gray-500 font-bold">מוצרים</p>
              </div>
              <div className="bg-white rounded-xl p-2 text-center border border-gray-100">
                <p className="text-lg font-black text-emerald-600">₪{(totalMarket - bundlePrice).toLocaleString()}</p>
                <p className="text-[9px] text-gray-500 font-bold">חיסכון</p>
              </div>
              <div className="bg-white rounded-xl p-2 text-center border border-gray-100">
                <p className="text-lg font-black text-amber-600">{bundle.participants}</p>
                <p className="text-[9px] text-gray-500 font-bold">משתתפים</p>
              </div>
            </div>
          </div>

          {/* Products breakdown */}
          <div className="bg-white rounded-2xl border border-gray-100 p-4">
            <div className="flex items-center justify-between mb-3">
              <h3 className="font-black text-gray-800 text-sm">🛒 מה כולל בחבילה</h3>
              <button onClick={() => setShowPicker(true)}
                className="flex items-center gap-1 px-3 py-1.5 bg-gradient-to-r from-indigo-500 to-violet-500 text-white font-bold rounded-lg text-xs hover:from-indigo-600 hover:to-violet-600 transition shadow-sm active:scale-95">
                <Plus className="w-3.5 h-3.5" /> הוסף מוצר
              </button>
            </div>
            <div className="space-y-3">
              {prods.map((p, i) => (
                <div key={i} className="flex items-center gap-3 bg-gray-50 rounded-xl p-3 border border-gray-100">
                  {p.image ? (
                    <img src={p.image} alt={p.name} className="w-12 h-12 rounded-lg object-cover flex-shrink-0" />
                  ) : (
                    <div className="w-12 h-12 rounded-lg bg-gray-200 flex items-center justify-center text-lg flex-shrink-0">📦</div>
                  )}
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-bold text-gray-900 truncate">{p.name}</p>
                    {p.marketPrice > 0 && <p className="text-xs text-gray-400">מחיר שוק: ₪{p.marketPrice.toLocaleString()}</p>}
                  </div>
                  <button onClick={() => handleRemoveProduct(i)}
                    title="הסר מהחבילה"
                    className="p-1.5 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition flex-shrink-0">
                    <X className="w-4 h-4" />
                  </button>
                </div>
              ))}
              {prods.length === 0 && (
                <div className="text-center py-6 text-gray-400">
                  <Package className="w-8 h-8 mx-auto mb-2 opacity-40" />
                  <p className="text-xs">החבילה ריקה — לחץ "הוסף מוצר" כדי להתחיל</p>
                </div>
              )}
            </div>

            {showPicker && (
              <ProductPickerForBundle
                onAddProduct={(product) => persistProds(prev => [...prev, product])}
                onClose={() => setShowPicker(false)}
                onViewFullDetails={onViewFullDetails}
              />
            )}

            <div className="mt-3 pt-3 border-t border-gray-100 flex items-center justify-between">
              <span className="text-xs text-gray-500">סה״כ שוק</span>
              <span className="text-sm text-gray-400 line-through">₪{totalMarket.toLocaleString()}</span>
            </div>
            <div className="flex items-center justify-between mt-1">
              <span className="text-sm font-black text-gray-900">מחיר חבילה</span>
              <span className="text-xl font-black text-indigo-600">₪{bundlePrice.toLocaleString()}</span>
            </div>
          </div>

          {/* Progress bar */}
          <div className="bg-white rounded-2xl border border-gray-100 p-4">
            <div className="flex items-center justify-between mb-2">
              <span className="text-xs font-bold text-gray-700">התקדמות הקבוצה</span>
              <span className="text-xs font-bold text-indigo-600">{progress}%</span>
            </div>
            <div className="h-2.5 bg-gray-100 rounded-full overflow-hidden">
              <div className={`h-full rounded-full bg-gradient-to-r ${bundle.color} transition-all`} style={{ width: `${progress}%` }} />
            </div>
            <p className="text-[10px] text-gray-400 mt-1.5">{bundle.participants} מתוך {bundle.maxParticipants} משתתפים · נשארו {bundle.daysLeft} ימים</p>
          </div>

          {/* CTA */}
          {joined ? (
            <div className="bg-emerald-50 border border-emerald-200 rounded-2xl p-4 text-center">
              <BadgeCheck className="w-8 h-8 text-emerald-500 mx-auto mb-2" />
              <p className="font-black text-emerald-800 text-sm">הצטרפת לחבילה!</p>
              <p className="text-xs text-emerald-600 mt-1">נעדכן אותך כשהקבוצה מתמלאת</p>
            </div>
          ) : (
            <button
              onClick={() => { setJoined(true); onJoin?.(bundle); }}
              className="w-full py-3.5 bg-gradient-to-r from-indigo-600 to-violet-600 hover:from-indigo-700 hover:to-violet-700 text-white font-black rounded-2xl text-sm transition shadow-lg shadow-indigo-200/50 active:scale-[0.98] flex items-center justify-center gap-2"
            >
              <Package className="w-4 h-4" />
              אני רוצה את החבילה הזו ✅
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────────
//  CREATE BUNDLE MODAL — wizard for creating custom bundles
// ─────────────────────────────────────────────────────────────────
const BUNDLE_TEMPLATES = [
  { id: "moving",  icon: "🏠", label: "מעבר דירה",   color: "from-rose-500 to-pink-500" },
  { id: "couple",  icon: "💑", label: "זוג צעיר",    color: "from-pink-500 to-fuchsia-500" },
  { id: "kitchen", icon: "🍳", label: "מטבח שלם",    color: "from-orange-500 to-amber-500" },
  { id: "baby",    icon: "👶", label: "תינוק חדש",   color: "from-sky-400 to-blue-500" },
  { id: "gaming",  icon: "🎮", label: "גיימינג",     color: "from-red-500 to-orange-500" },
  { id: "office",  icon: "💻", label: "עבודה מהבית", color: "from-emerald-500 to-teal-500" },
  { id: "custom",  icon: "✨", label: "חבילה מותאמת", color: "from-violet-500 to-indigo-500" },
];

function CreateBundleModal({ onClose, onCreate, onViewFullDetails }) {
  const [step, setStep] = useState(1); // 1=template, 2=products, 3=review
  const [template, setTemplate] = useState(null);
  const [title, setTitle] = useState("");
  const [products, setProducts] = useState([]);
  const [inputName, setInputName] = useState("");
  const [inputPrice, setInputPrice] = useState("");
  const [showPicker, setShowPicker] = useState(false);

  const handlePickTemplate = (t) => {
    setTemplate(t);
    setTitle(t.id === "custom" ? "" : ("חבילת " + t.label));
    setStep(2);
  };

  const handleAddProduct = () => {
    if (!inputName.trim()) return;
    setProducts(prev => [...prev, { name: inputName.trim(), image: "", marketPrice: parseInt(inputPrice) || 0 }]);
    setInputName("");
    setInputPrice("");
  };

  const handleRemove = (idx) => {
    setProducts(prev => prev.filter((_, i) => i !== idx));
  };

  const totalMarket = products.reduce((s, p) => s + p.marketPrice, 0);
  const bundlePrice = Math.round(totalMarket * 0.76);

  const handleCreate = () => {
    if (products.length < 2 || !title.trim()) return;
    const newBundle = {
      id: "bundle-custom-" + Date.now(),
      title: title.trim(),
      subtitle: products.map(p => p.name.split(" ").slice(0, 2).join(" ")).join(" + "),
      icon: template?.icon || "📦",
      color: template?.color || "from-violet-500 to-indigo-500",
      bg: "bg-violet-50",
      border: "border-violet-200",
      products,
      totalMarket,
      bundlePrice,
      participants: 1,
      maxParticipants: 50,
      daysLeft: 14,
      catIdx: 3,
      isCustom: true,
    };
    onCreate?.(newBundle);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-end sm:items-center justify-center" onClick={onClose}>
      <div className="bg-white w-full max-w-lg max-h-[90vh] overflow-y-auto rounded-t-3xl sm:rounded-3xl shadow-2xl" onClick={e => e.stopPropagation()}>
        {/* Header */}
        <div className="bg-gradient-to-r from-violet-600 to-indigo-600 p-5 rounded-t-3xl sm:rounded-t-3xl text-white relative">
          <button onClick={onClose} className="absolute top-4 left-4 w-8 h-8 bg-white/20 rounded-full flex items-center justify-center hover:bg-white/30 transition">
            <X className="w-4 h-4" />
          </button>
          <p className="text-2xl font-black">✨ צור חבילה חדשה</p>
          <p className="text-sm opacity-80 mt-1">בחר סוג חבילה, הוסף מוצרים, ושתף עם קבוצה</p>
          {/* Step indicators */}
          <div className="flex items-center gap-2 mt-3">
            {[1, 2, 3].map(s => (
              <div key={s} className={`h-1 flex-1 rounded-full transition ${s <= step ? "bg-white" : "bg-white/30"}`} />
            ))}
          </div>
        </div>

        <div className="p-5">
          {/* Step 1: Choose template */}
          {step === 1 && (
            <div className="space-y-3">
              <p className="text-sm font-bold text-gray-700 mb-3">מה אתה מחפש?</p>
              <div className="grid grid-cols-2 gap-3">
                {BUNDLE_TEMPLATES.map(t => (
                  <button
                    key={t.id}
                    onClick={() => handlePickTemplate(t)}
                    className="flex items-center gap-3 p-4 bg-gray-50 border border-gray-100 rounded-2xl hover:border-indigo-300 hover:bg-indigo-50 transition text-right"
                  >
                    <span className="text-2xl">{t.icon}</span>
                    <span className="text-sm font-bold text-gray-800">{t.label}</span>
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Step 2: Add products */}
          {step === 2 && (
            <div className="space-y-4">
              <button onClick={() => setStep(1)} className="flex items-center gap-1 text-indigo-600 text-xs font-bold mb-1">
                <ArrowLeft className="w-3 h-3" /> חזרה
              </button>
              <div>
                <label className="text-xs font-bold text-gray-600 mb-1 block">שם החבילה</label>
                <input
                  type="text"
                  value={title}
                  onChange={e => setTitle(e.target.value)}
                  placeholder="למשל: חבילת מטבח חלומי"
                  className="w-full px-4 py-2.5 border border-gray-200 rounded-xl text-sm focus:outline-none focus:border-indigo-300"
                />
              </div>
              <div>
                <label className="text-xs font-bold text-gray-600 mb-2 block">מוצרים בחבילה ({products.length})</label>
                {products.length > 0 && (
                  <div className="space-y-2 mb-3">
                    {products.map((p, i) => (
                      <div key={i} className="flex items-center gap-3 bg-gray-50 rounded-xl p-3">
                        <div className="w-8 h-8 bg-indigo-100 rounded-lg flex items-center justify-center text-xs font-black text-indigo-600">{i + 1}</div>
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-bold text-gray-900 truncate">{p.name}</p>
                          {p.marketPrice > 0 && <p className="text-[10px] text-gray-400">₪{p.marketPrice.toLocaleString()}</p>}
                        </div>
                        <button onClick={() => handleRemove(i)} className="p-1 text-red-400 hover:text-red-600 transition"><X className="w-3.5 h-3.5" /></button>
                      </div>
                    ))}
                  </div>
                )}
                <button onClick={() => setShowPicker(true)}
                  className="w-full py-2.5 bg-gradient-to-r from-indigo-500 to-violet-500 text-white font-bold rounded-xl text-sm hover:from-indigo-600 hover:to-violet-600 transition flex items-center justify-center gap-2 mb-2">
                  <Search className="w-3.5 h-3.5" />
                  בחר מוצר מהאתר
                </button>
                <p className="text-[10px] text-gray-400 text-center mb-2">— או הוסף ידנית —</p>
                <div className="flex gap-2">
                  <input
                    type="text"
                    value={inputName}
                    onChange={e => setInputName(e.target.value)}
                    onKeyDown={e => e.key === "Enter" && handleAddProduct()}
                    placeholder="שם מוצר"
                    className="flex-1 px-3 py-2 border border-gray-200 rounded-xl text-sm focus:outline-none focus:border-indigo-300"
                  />
                  <input
                    type="number"
                    value={inputPrice}
                    onChange={e => setInputPrice(e.target.value)}
                    onKeyDown={e => e.key === "Enter" && handleAddProduct()}
                    placeholder="מחיר ₪"
                    className="w-24 px-3 py-2 border border-gray-200 rounded-xl text-sm focus:outline-none focus:border-indigo-300"
                  />
                  <button onClick={handleAddProduct}
                    className="px-3 py-2 bg-indigo-600 text-white font-bold rounded-xl text-sm hover:bg-indigo-700 transition">
                    <Plus className="w-4 h-4" />
                  </button>
                </div>
                {showPicker && (
                  <ProductPickerForBundle
                    onAddProduct={(product) => {
                      setProducts(prev => [...prev, product]);
                    }}
                    onClose={() => setShowPicker(false)}
                    onViewFullDetails={onViewFullDetails}
                  />
                )}
              </div>
              {products.length >= 2 && (
                <button onClick={() => setStep(3)}
                  className="w-full py-3 bg-gradient-to-r from-indigo-600 to-violet-600 text-white font-black rounded-xl text-sm transition hover:from-indigo-700 active:scale-[0.98]">
                  המשך לסיכום →
                </button>
              )}
              {products.length < 2 && (
                <p className="text-[11px] text-gray-400 text-center">הוסף לפחות 2 מוצרים כדי להמשיך</p>
              )}
            </div>
          )}

          {/* Step 3: Review & Create */}
          {step === 3 && (
            <div className="space-y-4">
              <button onClick={() => setStep(2)} className="flex items-center gap-1 text-indigo-600 text-xs font-bold mb-1">
                <ArrowLeft className="w-3 h-3" /> חזרה לעריכה
              </button>
              <div className="bg-gradient-to-br from-violet-50 to-indigo-50 border border-violet-200 rounded-2xl p-4 text-center">
                <span className="text-3xl">{template?.icon || "📦"}</span>
                <p className="text-lg font-black text-gray-900 mt-2">{title}</p>
                <p className="text-xs text-gray-500 mt-1">{products.length} מוצרים</p>
              </div>
              <div className="space-y-2">
                {products.map((p, i) => (
                  <div key={i} className="flex items-center gap-3 bg-gray-50 rounded-xl p-3">
                    <span className="text-xs font-black text-indigo-600 bg-indigo-100 w-6 h-6 rounded-lg flex items-center justify-center">{i + 1}</span>
                    <span className="flex-1 text-sm font-bold text-gray-800 truncate">{p.name}</span>
                    {p.marketPrice > 0 && <span className="text-sm text-gray-400">₪{p.marketPrice.toLocaleString()}</span>}
                  </div>
                ))}
              </div>
              {totalMarket > 0 && (
                <div className="bg-white border border-gray-100 rounded-2xl p-4">
                  <div className="flex justify-between text-sm">
                    <span className="text-gray-500">סה״כ מחיר שוק</span>
                    <span className="text-gray-400 line-through">₪{totalMarket.toLocaleString()}</span>
                  </div>
                  <div className="flex justify-between text-sm mt-1">
                    <span className="font-black text-gray-900">יעד חבילה (24%- הנחה)</span>
                    <span className="font-black text-indigo-600 text-lg">₪{bundlePrice.toLocaleString()}</span>
                  </div>
                </div>
              )}
              <button onClick={handleCreate}
                className="w-full py-3.5 bg-gradient-to-r from-indigo-600 to-violet-600 hover:from-indigo-700 hover:to-violet-700 text-white font-black rounded-2xl text-sm transition shadow-lg shadow-indigo-200/50 active:scale-[0.98] flex items-center justify-center gap-2">
                <Sparkles className="w-4 h-4" />
                פרסם חבילה ✅
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────────
//  MOBILE BOTTOM NAV
// ─────────────────────────────────────────────────────────────────
function MobileBottomNav({ t, mode, setMode, wishlistCount, myProductsCount, onLoginClick }) {
  const items = [
    { id: "home",       icon: <Sparkles className="w-5 h-5" />,  label: t.navHome },
    { id: "search",     icon: <Search className="w-5 h-5" />,    label: t.navSearch },
    { id: "deals",      icon: <Tag className="w-5 h-5" />,       label: t.navDeals },
    { id: "myproducts", icon: <Package className="w-5 h-5" />,   label: "המוצרים שלי", badge: myProductsCount },
    { id: "wishlist",   icon: <Heart className="w-5 h-5" />,     label: t.navWishlist, badge: wishlistCount },
  ];
  return (
    <nav className="fixed bottom-0 left-0 right-0 z-40 md:hidden bg-white border-t border-gray-200 shadow-lg safe-bottom">
      <div className="flex items-center justify-around h-16">
        {items.map(item => (
          <button
            key={item.id}
            onClick={() => setMode(item.id)}
            className={`relative flex flex-col items-center gap-0.5 px-3 py-1 transition ${mode === item.id ? "text-indigo-600" : "text-gray-400"}`}
          >
            {item.icon}
            <span className="text-[10px] font-medium">{item.label}</span>
            {item.badge > 0 && (
              <span className="absolute -top-0.5 right-1 bg-red-500 text-white text-[9px] font-bold w-4 h-4 rounded-full flex items-center justify-center">{item.badge}</span>
            )}
          </button>
        ))}
      </div>
    </nav>
  );
}

